        expect(await runJev(['typesafe/jev-latest'])).toBeUndefined();

        vi.stubGlobal(
          'fetch',
          vi.fn(async (_url: string, _init: RequestInit) => ({
            ok: false,
            status: 401,
            json: async () => ({}),
          })),
        );
        expect(await runJev(['typesafe/jev-latest'])).toBeUndefined();

        vi.stubGlobal(
          'fetch',
          vi.fn(async (_url: string, _init: RequestInit) => {
            throw new Error('network down');
          }),
        );
        expect(await runJev(['typesafe/jev-latest'])).toBeUndefined();
