import asyncio

async def run(cmd, timeout=600):
    try:
        r = await pi.bash(command=cmd, settle=True, timeout=timeout)
        return {"cmd": cmd, "ok": r.get("ok"), "exit": r.get("exitCode"), "out": (r.get("output") or "")[-3000:]}
    except Exception as e:
        return {"cmd": cmd, "error": str(e)}

cmds = [
    'grep -rFq "api.typesafe.ai/v1/systemone" extensions/ && grep -rFq "jev-latest" extensions/ && grep -rFq "TYPESAFE_API_KEY" extensions/',
    '! grep -rEq "apikey_[0-9a-f]{16,}" extensions/ README.md model-router.example.json docs/',
    'grep -rFiq "jev" model-router.example.json && grep -rFiq "jev" README.md',
    'grep -rFq "TYPESAFE_API_KEY" extensions/ && ! grep -rEq "apikey_[0-9a-f]{16,}" extensions/ README.md model-router.example.json docs/',
    'npx tsc --noEmit',
]
res = await asyncio.gather(*[run(c) for c in cmds])
return res

